import os, select, signal, subprocess, sys, termios, time
# Open-producer feeder: runs SHELL -c CMD with stdin and stdout each on a pipe or on one private pty
# (OPOST and ECHO off so output bytes are exact; ICANON on when the pty is the input). Each CHUNK (hex)
# is written while the input stays open; the helper then waits until the output has been quiet for
# 200 ms and the process is blocked (state S on 5 consecutive samples), and saves the bytes delivered
# so far as chunkN / cumN. Then it ends the input (pipe close, or VEOF on the pty), saves the rest as
# 'final', reaps the child and prints its status. The child stays in this session and ignores SIGHUP.
shell, cmd, inmode, outmode = sys.argv[1:5]
chunks = [bytes.fromhex(c) for c in sys.argv[5:]]
m = s = None
if 'pty' in (inmode, outmode):
    m, s = os.openpty()
    a = termios.tcgetattr(s)
    a[1] &= ~termios.OPOST
    a[3] &= ~(termios.ECHO | termios.ECHONL)
    termios.tcsetattr(s, termios.TCSANOW, a)
if inmode == 'pipe':
    child_in, feed_fd = os.pipe()
else:
    child_in, feed_fd = s, m
if outmode == 'pipe':
    read_fd, child_out = os.pipe()
else:
    read_fd, child_out = m, s
err = open('feed-stderr', 'wb')
child = subprocess.Popen([shell, '--noprofile', '--norc', '-c', cmd], stdin=child_in, stdout=child_out,
                         stderr=err, close_fds=True, preexec_fn=lambda: signal.signal(signal.SIGHUP, signal.SIG_IGN))
for fd in {child_in, child_out}:
    os.close(fd)
got = bytearray()
def read_some(timeout):
    if select.select([read_fd], [], [], timeout)[0]:
        try:
            data = os.read(read_fd, 65536)
        except OSError:
            return None
        if not data:
            return None
        got.extend(data)
        return True
    return False
def blocked():
    try:
        return open('/proc/%d/stat' % child.pid).read().rsplit(')', 1)[1].split()[0] == 'S'
    except OSError:
        return False
def settle():
    deadline = time.monotonic() + 10
    quiet_since, run = time.monotonic(), 0
    while time.monotonic() < deadline:
        r = read_some(0.02)
        if r:
            quiet_since, run = time.monotonic(), 0
            continue
        if r is None:
            return
        run = run + 1 if blocked() else 0
        if run >= 5 and time.monotonic() - quiet_since >= 0.2:
            return
mark = 0
for i, c in enumerate(chunks, 1):
    os.write(feed_fd, c)
    settle()
    open('chunk%d' % i, 'wb').write(bytes(got[mark:]))
    open('cum%d' % i, 'wb').write(bytes(got))
    mark = len(got)
if inmode == 'pipe':
    os.close(feed_fd)
else:
    os.write(feed_fd, b'\x04')
deadline = time.monotonic() + 10
while time.monotonic() < deadline:
    if read_some(0.05) is None:
        break
    if child.poll() is not None and not select.select([read_fd], [], [], 0)[0]:
        break
open('final', 'wb').write(bytes(got[mark:]))
try:
    status = child.wait(timeout=10)
except subprocess.TimeoutExpired:
    child.kill(); status = child.wait(); print('killed-after-timeout')
print('child-exit %d' % status)

